import React from "react";
import {
  TiStarFullOutline,
  TiStarHalfOutline,
  TiStarOutline,
} from "react-icons/ti";

function RatingStars({ rating = 0, size = 20 }) {
  // Ensure rating is between 0 and 5
  const clampedRating = Math.min(5, Math.max(0, Number(rating) || 0));
  const fullStars = Math.floor(clampedRating);
  const hasHalfStar = clampedRating % 1 >= 0.5;
  const emptyStars = 5 - fullStars - (hasHalfStar ? 1 : 0);

  return (
    <div className="flex gap-1 text-yellow-100">
      {[...Array(fullStars)].map((_, i) => (
        <TiStarFullOutline key={`full-${i}`} size={size} />
      ))}
      {hasHalfStar && <TiStarHalfOutline key="half" size={size} />}
      {[...Array(emptyStars)].map((_, i) => (
        <TiStarOutline key={`empty-${i}`} size={size} />
      ))}
    </div>
  );
}

export default RatingStars;
